generated_sql:
SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age
FROM singer
WHERE Country = 'France';

SELECT singer.Country, COUNT(singer.Singer_ID) AS Number_of_Singers
FROM singer
GROUP BY singer.Country;

SELECT Country, COUNT(DISTINCT Singer_ID) AS NumberOfSingers
FROM singer
GROUP BY Country;

SELECT COUNT(DISTINCT concert_ID) AS NumberOfConcerts
FROM concert
WHERE YEAR = '2014' OR YEAR = '2015';

SELECT DISTINCT s.Name 
FROM singer AS s
WHERE NOT EXISTS (
    SELECT 1 FROM concert AS c
    WHERE c.Stadium_ID = s.Stadium_ID
);

SELECT DISTINCT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID FROM singer_in_concert GROUP BY Stadium_ID HAVING COUNT(DISTINCT Singer_ID) > 1
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID;

SELECT COUNT(CASE WHEN IS_male = 1 THEN 1 ELSE NULL END) AS Male_Singers,
       COUNT(CASE WHEN IS_male = 0 THEN 1 ELSE NULL END) AS Female_Singers
FROM singer;

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS AvgCapacity
    FROM stadium
    GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity < T2.AvgCapacity;

SELECT singer.Name FROM singer
JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID
JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID;

SELECT singer.Name FROM singer 
WHERE NOT EXISTS (
    SELECT 1 FROM concert 
    WHERE concert.Singer_ID = singer.Singer_ID
);

SELECT s.Name FROM singer s
JOIN concert c ON s.Singer_ID = c.concert_ID
WHERE c.Year > 2013;

SELECT c.Year FROM concert c JOIN (
    SELECT concert_ID, COUNT(*) AS concert_count
    FROM singer_in_concert sic
    GROUP BY concert_ID
) sc ON c.concert_ID = sc.concert_ID
ORDER BY sc.concert_count DESC LIMIT 1;

SELECT c.concert_Name FROM concert AS c JOIN (
    SELECT Stadium_ID, MAX(Capacity) AS max_capacity
    FROM concert
    GROUP BY Stadium_ID
) AS smc ON c.Stadium_ID = smc.Stadium_ID AND c.Capacity = smc.max_capacity;
